        title: 'The Saver-Borrower Dilemma: Why Direct Finance Fails Everyday Citizens',
        body: 'Imagine an economy with no banks or intermediaries. You have saved ₹1,00,000 from your salary and want to earn a return. A local entrepreneur wants to borrow ₹50,00,000 for 10 years to build a textile unit.\n\nCould you directly lend your ₹1,00,000 to this entrepreneur? Direct lending faces four fatal frictions:\n1. **Size Mismatch**: You have ₹1,00,000; the factory needs ₹50,00,000.\n2. **Maturity & Liquidity Mismatch**: You might need your cash back in 6 months for medical needs; the factory cannot repay for 10 years.\n3. **Information Asymmetry**: How do you know if the entrepreneur is honest, competent, or running a fraudulent scheme?\n4. **Risk Concentration**: If the textile unit goes bankrupt, 100% of your life savings vanishes.\n\nFinancial intermediaries (banks) solve these problems simultaneously by pooling thousands of small, short-term deposits to fund large, long-term, screened loans while guaranteeing on-demand liquidity to savers.',
        order: 1,
