        body: '### Critical Examiner Traps\n- **Trap 1: Scheduled Bank Capital Criteria**: Section 42(6)(a) of the RBI Act specifies a statutory historical threshold of **₹5 Lakh** for Second Schedule inclusion. (Do not confuse this statutory minimum for Second Schedule with modern licensing guidelines requiring ₹500 Crore / ₹1,000 Crore capital for starting a new bank!).\n- **Trap 2: SBI vs Nationalized Banks**: SBI is governed by the **State Bank of India Act, 1955**, whereas Nationalized Banks (PNB, BoB, Canara Bank, etc.) are governed by the **Banking Companies (Acquisition and Transfer of Undertakings) Acts, 1970/1980**.\n- **Trap 3: Foreign Bank PSL Target**: Foreign banks with **20 or more branches** have the **same 40% PSL target** as domestic commercial banks.\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: Second Schedule Section 42 criteria, Foreign Bank WOS model, and PSB merger architecture.\n- **SBI/IBPS PO, NABARD & RPSC RAS**: List of 12 PSBs, Old vs New private banks, and scheduled bank privileges.',
