        title: 'Universal vs Differentiated Banking: Tailoring Banks to Specific Economic Needs',
        body: 'For decades, India followed a **Universal Banking** philosophy: every licensed bank was expected to do everything—accept deposits, fund giant steel factories, open rural branches, issue credit cards, and provide foreign exchange services.\n\nHowever, universal banks naturally gravitated toward large corporate loans and wealthy urban centers, neglecting small farmers, street vendors, and micro-enterprises. Following the **Nachiket Mor Committee Report (2014)**, the RBI shifted to a **Differentiated Banking Architecture**—licensing specialized, "niche" banks designed from the ground up to solve specific financial inclusion bottlenecks:\n- **Small Finance Banks (SFBs)**: To provide savings and micro-credit to small business units and unorganized sector workers.\n- **Payments Banks**: To build high-volume, low-value digital payment pipelines and mobilize remittances without taking credit risk.',
