        type: 'CORE_IDEA',
        title: 'Comparative Architecture: Universal Banks vs SFBs vs Payments Banks vs RRBs',
        body: 'The four banking models differ across regulatory mandates, lending rights, and ownership:\n\n| Dimension | Universal Commercial Banks | Small Finance Banks (SFBs) | Payments Banks | Regional Rural Banks (RRBs) |\n| :--- | :--- | :--- | :--- | :--- |\n| **Core Philosophy** | Full-service banking across all sectors | Financial inclusion through micro-lending & savings | Transaction banking & remittance pipes (Zero credit risk) | Rural & agricultural credit mobilization |\n| **Deposit Acceptance** | Demand & Time Deposits (No Cap) | Demand & Time Deposits (No Cap) | **Demand Deposits Only** (Max **₹2 Lakh** per customer) | Demand & Time Deposits (No Cap) |\n| **Lending Activities** | Permitted across all sectors & sizes | **Permitted** (Focus on micro/small loans) | **STRICTLY PROHIBITED** (Zero lending) | **Permitted** (Focus on rural/agriculture) |\n| **Credit Cards** | Can issue Credit & Debit Cards | Can issue Credit & Debit Cards | **Can issue ATM/Debit Cards ONLY** (No Credit Cards) | Can issue Credit & Debit Cards |\n| **PSL Mandate** | **40%** of ANBC | **75%** of ANBC | N/A (Cannot lend) | **75%** of ANBC |\n| **Small Ticket Lending**| Discretionary | **$\ge 50\%$** of loans $\le$ ₹25 Lakh | N/A | Focus on small/marginal farmers |\n| **SLR Deployment** | Standard SLR (Currently 18%) | Standard SLR (18%) | **$\ge 75\%$ of demand deposits** in G-Secs/T-Bills (up to 1-yr) | Standard SLR (18%) |\n| **Minimum CRAR** | **9%** (11.5% with CCB) | **15%** (Higher capital buffer) | **15%** (Tier 1 leverage focus) | **9%** |',
