        type: 'MECHANISM',
        title: 'Institutional Mechanics of RRBs & SFB Evolution',
        body: '### 1. Regional Rural Banks (RRBs - RRB Act, 1976)\n- Created following the **Narasimham Working Group (1975)** to combine the local familiarity of cooperatives with the modern business acumen of commercial banks.\n- **Statutory Equity Tripartite Structure**:\n  $$\\text{Central Government: } 50\\% \\quad | \\quad \\text{Sponsor Bank: } 35\\% \\quad | \\quad \\text{State Government: } 15\\%$$\n- **Consolidation**: Amalgamations reduced RRBs from 196 in the 1980s to **43 RRBs** operating on a "One State, One RRB" (or contiguous region) model under NABARD supervisory oversight.\n\n### 2. Small Finance Banks: Transition & "On-Tap" Licensing\n- Promoters: Primarily converted Microfinance Institutions (NBFC-MFIs like Equitas, Ujjivan) and Local Area Banks (Capital Small Finance Bank).\n- **On-Tap Licensing (2019)**: Minimum initial paid-up capital of **₹200 Crore** (₹300 Crore for universal transition eligibility after 5 years of successful operations).\n- **Branch Requirement**: At least **$25\\%$ of branches** must be in unbanked rural centers.',
