        type: 'EXAM_APPLICATION',
        title: 'Exam Traps & Multi-Exam Crosswalks',
        body: '### Critical Examiner Traps\n- **Trap 1: Indicators in Revised PCA (2022)**: The revised PCA framework tracks **THREE indicators: (1) Capital (CRAR/CET1), (2) Asset Quality (Net NPA), and (3) Leverage**. Profitability (Return on Assets / RoA) was **REMOVED** as a trigger indicator in the 2021 revision.\n- **Trap 2: Gross vs Net NPA in PCA**: PCA triggers are based on **Net NPA ratio** ($\ge 6.0\\%$), NOT Gross NPA.\n- **Trap 3: Does PCA apply to NBFCs?**: In December 2021, RBI introduced a **separate PCA framework for NBFCs** (Middle, Upper, and Top Layers), effective October 2022.\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: CAMELS components, Revised PCA 2022 triggers (Net NPA 6%, CET1 thresholds), and BFS composition.\n- **IIBF DBF, SBI/IBPS PO & RPSC RAS**: Definitions of CAMELS, purpose of PCA, and mandatory restrictions under PCA.',
