        title: 'The Shock Absorber: Why Bank Capital Protects Depositors from Ruin',
        body: 'Why cannot a bank operate with 100% deposit liabilities and zero equity capital?\n\nSuppose a bank has ₹100 Crore in deposits and ₹100 Crore in corporate loans, with ₹0 equity capital. If a single factory defaults on a ₹2 Crore loan, the bank\'s assets fall to ₹98 Crore. The bank is now **insolvent** and cannot repay its depositors in full!\n\n**Bank Capital (CRAR)** is the bank\'s unencumbered equity shock-absorber. If the bank has ₹12 Crore in equity capital and ₹100 Crore in deposits (Total Assets = ₹112 Crore), a ₹5 Crore loan default is absorbed entirely by the equity shareholders. Depositors still get 100% of their money back. Capital adequacy regulations ensure banks hold enough equity to survive severe economic recessions without failing.',
        order: 1,
