        body: '### 1. Risk-Weighted Assets (RWA) Computation\nInstead of treating all assets equally, each asset is multiplied by a regulatory Risk Weight ($RW$):\n- **Cash & Sovereign G-Secs**: $RW = 0\\%$ (Risk-free).\n- **Claims on Banks (AAA Rated)**: $RW = 20\\%$.\n- **Prime Residential Home Loans (LTV $\\le 80\\%$)**: $RW = 35\\% - 50\\%$.\n- **Standard Rated Corporate Loans**: $RW = 20\\%$ (AAA) to $150\\%$ (Unrated/D-rated).\n- **Unsecured Consumer Loans / Credit Cards**: $RW = 125\\% - 150\\%$ (High risk penalty).\n\n$$\\text{Total Credit RWA} = \\sum (\\text{Asset Value}_i \\times RW_i) + \\sum (\\text{Off-Balance Sheet Credit Conversion Factor} \\times RW)$$\n\n### 2. The Capital Conservation Buffer (CCB = 2.5%)\n- Mandated to be held entirely in pure **Common Equity Tier 1 (CET1)**.\n- Built up outside periods of stress. When a bank\'s capital falls into the CCB band ($5.5\\% - 8.0\\%$ CET1), the bank faces automatic legal restrictions on paying dividends, share buybacks, and executive bonuses until the buffer is rebuilt.',
