        title: 'The Slippage Pipeline: From Performing Loan to Irrecoverable Loss',
        body: 'When a bank lends ₹10 Crore to an automobile components firm, the loan does not suddenly collapse overnight. Financial distress follows a predictable deterioration path:\n1. **First 30 Days (Cash Flow Hiccup)**: The firm delays its monthly EMI by 15 days due to late customer receipts (SMA-0).\n2. **60 Days (Operational Stress)**: The firm fails to pay two consecutive EMIs (SMA-1).\n3. **90 Days (Critical Distress)**: Three EMIs missed; insolvency risk is severe (SMA-2).\n4. **Day 91 (The Cliff Edge)**: The account legally crosses into **Non-Performing Asset (NPA)** territory. The bank must immediately stop booking accrued interest income and start locking away real capital as **Provisions**.\n\nEarly identification via Special Mention Accounts (SMA) ensures banks intervene to restructure viable firms before irreversible default occurs.',
