        type: 'MECHANISM',
        title: 'Gross NPA vs Net NPA & The Provisioning Coverage Ratio (PCR)',
        body: 'To evaluate a bank\'s true balance sheet health, analysts look at Gross NPA, Net NPA, and PCR:\n\n### 1. Gross NPA vs Net NPA\n- **Gross NPA (GNPA)**: The total face value of all loans classified as NPAs on the bank\'s balance sheet.\n$$\\text{GNPA Ratio} = \\left(\\frac{\\text{Gross NPAs}}{\\text{Gross Total Advances}}\\right) \\times 100$$\n- **Net NPA (NNPA)**: The real residual default risk remaining on the bank\'s books after deducting loan loss provisions, claims received from ECGC/DICGC, and partial write-offs:\n$$\\text{Net NPA} = \\text{Gross NPA} - (\\text{Cumulative Provisions} + \\text{ECGC/DICGC Claims} + \\text{Interest in Suspense})$$\n$$\\text{NNPA Ratio} = \\left(\\frac{\\text{Net NPAs}}{\\text{Net Total Advances}}\\right) \\times 100$$\n\n### 2. Provisioning Coverage Ratio (PCR)\n$$\\text{PCR} = \\left(\\frac{\\text{Total Loan Loss Provisions Held}}{\\text{Gross NPAs}}\\right) \\times 100$$\n- **Why PCR is Vital**: A high PCR (e.g., $75\\% - 85\\%$) means the bank has already set aside cash from past profits to absorb $80\\%$ of its bad loans. Even if borrowers default completely, future bank profits and capital will not be damaged.',
