        type: 'INTUITION',
        title: 'Ending the Debtor\'s Paradise: The Shift from Recovery to Time-Bound Resolution',
        body: 'Prior to 2016, India was known as a "Debtor\'s Paradise". When a promoter defaulted on a ₹5,000 Crore bank loan, the bank spent 10 to 15 years filing cases in civil courts and Debt Recovery Tribunals (DRTs). While the court cases dragged on, the promoter continued living lavishly and controlling the company, while the factory assets rusted away and banks bled red ink.\n\nThe enactment of the **Insolvency and Bankruptcy Code (IBC, 2016)** revolutionized Indian credit culture. It introduced a **Creditor-in-Control** model: the moment a corporate borrower defaults on ₹1 Crore, the promoter loses management control, and a professional Resolution Professional takes over the company to sell it to the highest bidder within 180 days.',
        order: 1,
