        type: 'MECHANISM',
        title: 'RBI June 7, 2019 Prudential Framework & The NARCL Dual Structure',
        body: '### 1. RBI Prudential Framework for Resolution of Stressed Assets (June 7, 2019)\n- Enacted after the Supreme Court struck down the February 12, 2018 circular (Dharani Sugars case).\n- **30-Day Review Period**: The moment a borrower defaults (Day 1), lenders get a 30-day review period to design a resolution strategy.\n- **Inter-Creditor Agreement (ICA)**: Lenders sign an ICA where decisions approved by **$75\\%$ of lenders by value and $60\\%$ of lenders by number** are legally binding on all lenders.\n- **180-Day Resolution Window**: If a Resolution Plan (RP) is not implemented within 180 days, banks must make **additional penal provisions** ($20\\%$ after 180 days, and an additional $15\\%$ after 365 days, totaling $35\\%$ extra provision).\n\n### 2. The NARCL-IDRCL "Bad Bank" Architecture\n- **NARCL (Public Sector Asset Reconstruction Company)**: Majority owned ($51\\%$) by Public Sector Banks. Acquires stressed loans from banks.\n- **IDRCL (India Debt Resolution Company Limited)**: Majority owned ($51\\%$) by Private Sector Lenders. Acts as the specialized asset management agency to turn around and liquidate the operational assets.\n- **Government Guarantee**: The Union Government provides a sovereign backstop guarantee on the 85% Security Receipts for up to 5 years, covering any shortfall between realized value and face value.',
