        title: 'The Digital Plumbing: How Money Moves Instantly Across India',
        body: 'When you scan a QR code at a street tea stall and pay ₹15 using UPI, what happens behind the scenes?\n\nWithin 1.5 seconds, money is debited from your private bank in Mumbai and credited to the tea vendor\'s cooperative bank in Jaipur. You never shared your bank account number or IFSC code, and the transaction cost zero fees.\n\nIndia operates the most advanced digital payment infrastructure in the world. Built on open, interoperable public digital rails governed by the **National Payments Corporation of India (NPCI)** and regulated by the **RBI**, this payment ecosystem processes over 13 Billion instant UPI transactions every month.',
