        title: 'The Retail Digital Rails: NPCI Product Architecture',
        body: 'Incorporated under the PSSA 2007 by RBI and the Indian Banks\' Association (IBA), NPCI manages the retail payment rails:\n\n```\n                      NPCI RETAIL PAYMENT ECOSYSTEM\n                                    │\n     ┌──────────────────┬───────────┴───────────┬──────────────────┐\n     ▼                  ▼                       ▼                  ▼\nUPI (2016)          IMPS (2010)             AePS (2011)        NACH / BBPS\n• Interoperable VPA • 24x7 instant credit   • Biometric Micro- • NACH: High-volume recurring\n  (xyz@okhdfcbank)    up to ₹5 Lakh           ATM withdrawals    mandates (SIPs, EMIs, salary)\n• 1-click 2-factor  • Uses Mobile Number      using Aadhaar    • BBPS: Interoperable utility\n  PIN authentication  + MMID or Acc/IFSC    • Fingerprint auth   bill payment ecosystem\n• Single API rail   • Core engine for UPI   • Grassroots BCs   • NETC: FASTag toll collection\n```\n\n### UPI Innovations\n- **UPI 123Pay**: Feature phone payments via IVR, missed call, or sound-based tech (no internet required).\n- **UPI Lite**: On-device wallet for small offline transactions (up to ₹500 per transaction, wallet balance up to ₹2,000) without PIN.\n- **Credit on UPI**: Pre-sanctioned credit lines and RuPay credit cards linked directly to UPI.',
