        title: 'Shadow Banking: The Nimble Lenders with Hidden Fault Lines',
        body: 'Why do NBFCs exist if we already have commercial banks?\n\nTraditional banks are heavily regulated, bureaucratic, and slow. If a truck driver needs a ₹15,00,000 loan to buy a second-hand commercial truck, a large PSB might reject him because he lacks formal tax returns.\n\nAn **NBFC (like Shriram Finance or Bajaj Finance)** steps in: its loan officer meets the driver in person, inspects the truck, evaluates daily freight income, and disburses the loan in 48 hours.\n\nNBFCs are agile credit innovators that reach unbanked MSMEs. However, because NBFCs cannot take sticky retail savings deposits, they fund these loans by borrowing short-term money from mutual funds and corporate debt markets. When financial markets panic, this short-term funding vanishes overnight, sparking a systemic **liquidity freeze**.',
