        body: '### The Anatomy of the 2018 IL&FS Collapse\n1. **The Dangerous Business Model**: Infrastructure Leasing & Financial Services (IL&FS) had a balance sheet of ₹91,000 Crore. It funded 20-year highway, tunnel, and energy projects by issuing **30-day to 90-day Commercial Paper (CP)** to mutual funds.\n2. **The Liquidity Freeze**: In September 2018, IL&FS defaulted on a ₹1,000 Crore CP obligation. Mutual funds that held IL&FS paper faced massive investor redemption panic and instantly stopped buying CP from all other NBFCs and Housing Finance Companies (DHFL, Reliance Capital).\n3. **The Systemic Contagion Channel**:\n\n```\n                      THE SHADOW BANKING CONTAGION SPILLOVER\n                                        │\n         ┌──────────────────────────────┼──────────────────────────────┐\n         ▼                              ▼                              ▼\nNBFC DEFAULT (IL&FS/DHFL)      MUTUAL FUND PANIC              BANK BALANCE SHEET STRESS\n• Short-term CP rollover      • Debt mutual funds suffer     • Banks hold 60% of total\n  fails completely              redemption runs                NBFC wholesale bank loans\n• Construction & capex loans  • Liquidity drying up across   • Risk of fresh systemic\n  freeze nationwide             commercial paper market        NPA wave across banks\n```\n\n*The Regulatory Response*: To prevent repeat contagions, the Central Government superseded the board of IL&FS (invoking Section 241/242 of Companies Act), and RBI completely overhauled NBFC oversight via **Scale-Based Regulation (SBR)**.',
