        type: 'MECHANISM',
        title: 'Specialized NBFC Typologies: HFCs, ARCs, and Harmonized Microfinance',
        body: 'The Indian financial ecosystem features specialized NBFC categories tailored for specific asset classes:\n\n### 1. Housing Finance Companies (HFCs)\n- **Regulatory Shift**: Transferred from **National Housing Bank (NHB)** to **RBI** under the Finance Act, 2019.\n- **Principal Business Criteria (PBC)**: At least **$60\\%$ of total assets** must be in housing finance, and at least **$50\\%$ of total assets** must be in individual housing loans.\n\n### 2. Asset Reconstruction Companies (ARCs)\n- Registered under Section 3 of the **SARFAESI Act, 2002**.\n- Mandate: Securitization and reconstruction of stressed bank loans.\n- **Revised Capital Norms (2022)**: Minimum Net Owned Funds (NOF) requirement raised to **₹300 Crore** (phased by 2026).\n\n### 3. Harmonized Microfinance Framework (April 2022)\n- Standardized microfinance regulations across Banks, SFBs, NBFC-MFIs, and Cooperatives.\n- **Microfinance Loan Definition**: A collateral-free loan provided to a household having an **annual income of up to ₹3,00,000**.\n- **Repayment Cap**: Monthly loan repayment obligations cannot exceed **$50\\%$ of monthly household income**.',
