        title: 'The Safety Cushion: Preventing the Domino Effect in Banking',
        body: 'Why does the collapse of a textile factory cause zero panic, while the collapse of a single mid-sized bank can freeze an entire economy?\n\nBecause banks are deeply interconnected through interbank deposits, payment clearing, and public psychology. If depositors see one bank shutter its doors, fear spreads like wildfire: "What if my bank is next?" Depositors rush to pull cash out of every bank in the city (contagion run).\n\nTo prevent this domino effect, modern economies construct a **Three-Layer Safety Net**:\n1. **Lender of Last Resort (RBI)**: Provides instant emergency cash to solvent banks.\n2. **Deposit Insurance (DICGC)**: Guarantees that small depositors will get up to ₹5 Lakh back even if their bank goes bankrupt.\n3. **D-SIB Regulation**: Forces "Too Big to Fail" banks to hold extra equity capital so they never fail in the first place.',
