        title: 'Domestic Systemically Important Banks (D-SIBs): "Too Big to Fail"',
        body: 'Under RBI\'s D-SIB framework, banks with systemic footprints exceeding $2\\%$ of Indian GDP are assessed across four quantitative parameters:\n1. **Size** ($40\\%$ weight) | 2. **Interconnectedness** ($20\\%$ weight) | 3. **Substitutability** ($20\\%$ weight) | 4. **Complexity** ($20\\%$ weight).\n\n### The D-SIB Bucketing & Additional Capital Surcharges\n\n| Bucket | Additional CET1 Surcharge | Designated Banks in India (Current) |\n| :--- | :--- | :--- |\n| **Bucket 5** | $+1.00\\%$ of RWA | *(Empty)* |\n| **Bucket 4** | $+0.80\\%$ of RWA | **State Bank of India (SBI)** (Shifted to Bucket 4) |\n| **Bucket 3** | $+0.60\\%$ of RWA | *(Empty)* |\n| **Bucket 2** | $+0.40\\%$ of RWA | **HDFC Bank** (Shifted to Bucket 2 post-HDFC merger) |\n| **Bucket 1** | $+0.20\\%$ of RWA | **ICICI Bank** |\n\n*Why Surcharges Matter*: Because a government bailout of SBI or HDFC Bank would cost trillions in taxpayer money, the RBI forces these mega-banks to maintain higher CET1 capital buffers ($11.7\\% - 12.3\\%$ total CRAR) during normal times.',
